#!/usr/bin/env python3
"""Assemble results/RESULTS_SUMMARY.md from the saved result files. No number is typed by hand."""
import json, os, csv
import pandas as pd
P = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", ".."))
J = lambda f: json.load(open(os.path.join(P, f)))
flow = J("data/derived/faers_q/report_flow.json"); sb = J("data/derived/faers_q/b/summary.json")
h1 = J("results/tables/primary_H1_faersq_b_clean.json"); nc = J("results/tables/null_coverage_faersq_b_clean.json")
cm = J("results/tables/comention_summary.json"); h2 = J("results/tables/h2_regression.json"); h3 = J("results/tables/asof_summary.json")
h4 = J("results/tables/primary_H4_ctgov_all.json"); h4r = J("results/tables/primary_H4_ctgov_no_shared_condition.json")
ct = J("data/derived/ctgov/profile/summary.json"); at = J("data/derived/ctgov/attribution_summary.json")
p2 = J("private/reviews/P2_numbers.json") if os.path.exists(os.path.join(P, "private/reviews/P2_numbers.json")) else {}
grid = pd.read_csv(os.path.join(P, "results/tables/sensitivity_grid.csv")).drop_duplicates(["extraction", "ranking", "K", "cleaned"])
man = list(csv.DictReader(open(os.path.join(P, "data/raw/faers_quarterly/MANIFEST.tsv")), delimiter="\t"))
f = lambda x: f"{x:,}"
L = []; A = L.append
A("# Results summary — every number below is read from a saved result file\n")
A("Generated by `code/python/make_results_summary.py`. Source file in brackets. Extraction (b) = primary + secondary suspect drugs, fixed-dose-combination-only mentions excluded.\n")
A("## 1. Data flow (FAERS quarterly files) [`data/raw/faers_quarterly/MANIFEST.tsv`, `data/derived/faers_q/report_flow.json`]")
A(f"- Quarterly files: {len(man)} (2004Q1–2026Q3), {sum(int(r['zip_bytes']) for r in man)/1e9:.2f} GB zipped; lines skipped as malformed: {sum(int(r.get('skipped_lines') or 0) for r in man)}.")
A(f"- DEMO rows (all case versions): {f(flow['demo_rows_all_versions'])}; cases after deduplication: {f(flow['cases_after_dedup'])} ({f(flow['cases_legacy_era'])} from the legacy AERS era).")
A(f"- Drug rows in deduplicated cases: {f(flow['drug_rows_in_dedup_cases'])}; by mapping source: " + ", ".join(f"{k} {f(v)}" for k, v in flow['drug_rows_by_mapping_source'].items()) + ".")
A(f"- Cases with at least one mapped ingredient: {f(flow['reports_with_a_mapped_drug'])}; ingredients seen: {f(flow['ingredients_seen'])}; distinct preferred terms: {f(flow['distinct_pt'])}; cases with a reaction: {f(flow['reports_with_a_reaction'])}.")
A("\n## 2. Cohort, extraction (b) [`data/derived/faers_q/b/summary.json`]")
A(f"- Background cases: {f(sb['reports_in_background'])}. Molecules with ≥100 reports: {f(sb['eligible_molecules'])}. Cohort: {f(sb['cohort_molecules'])} molecules at {sb['cohort_targets']} targets; {f(h1['same_target_pairs'])} same-target and {f(h1['different_target_pairs'])} different-target pairs.")
A(f"- Signals in cohort: {f(sb['signals_cohort'])} ({f(sb['clean_signals_cohort'])} after cleaning). Cleaning removes {sb['removed_from_top20_pct']}% of raw top-20 slots. Median cleaned signals per molecule: {sb['median_clean_signals_per_molecule']}; molecules with fewer than 20: {sb['pct_molecules_under_20_clean_signals']}%.")
A("\n## 3. H1 — primary [`results/tables/primary_H1_faersq_b_clean.json`, `null_coverage_faersq_b_clean.json`]")
x, j = h1["shared_signals"], h1["jaccard"]
A(f"- Null-coverage check before reading H1: rejection rate {nc['rejection_rate_at_0025']} at one-sided 0.025 over {nc['null_datasets']} null datasets; 95% interval contained zero in {nc['ci_contains_zero_rate']*100:.0f}%.")
A(f"- Δ (molecule-averaged difference in shared top-20 signals) = **{x['delta']}** (95% CI {x['ci95'][0]}–{x['ci95'][1]}); permutation p = {x['p_perm_one_sided']} (9,999 permutations; largest null value {x['perm_null_max']}).")
A(f"- Pair means (descriptive): same target {x['pair_mean_same']}, different target {x['pair_mean_different']}. Jaccard contrast {j['delta']} (95% CI {j['ci95'][0]}–{j['ci95'][1]}).")
hx = J("results/tables/primary_H1_faersq_b_clean_excess.json")["excess"]; ka = J("results/tables/primary_grid_b_prr_kall_clean.json"); ex = J("results/tables/descriptives_extra.json")
A(f"- Excess-overlap contrast (observed minus expected overlap given profile sizes and term prevalence) Δ_X = {hx['delta']} (95% CI {hx['ci95'][0]}–{hx['ci95'][1]}; p {hx['p_perm_one_sided']}); mean excess {hx['pair_mean_same']} for same-target and {hx['pair_mean_different']} for different-target pairs. θ (rank-based measure in the plan) was not computed.")
A(f"- All cleaned signals instead of the top 20 (K = all; 999 permutations, 1,000 bootstrap): Δ = {ka['shared_signals']['delta']} (95% CI {ka['shared_signals']['ci95'][0]}–{ka['shared_signals']['ci95'][1]}); pair means {ka['shared_signals']['pair_mean_same']} vs {ka['shared_signals']['pair_mean_different']}; Jaccard contrast {ka['jaccard']['delta']} ({ka['jaccard']['ci95'][0]}–{ka['jaccard']['ci95'][1]}).")
A(f"- Descriptives [`results/tables/descriptives_extra.json`]: latest FDA receipt date in the data {ex['latest_fda_receipt_date']}; distinct primary identifiers {f(ex['distinct_primary_ids'])}; cases with a health-professional reporter {f(ex['cases_health_professional_reporter'])}; suspect reports per cohort molecule: median {ex['cohort_reports_median']:.0f} (IQR {ex['cohort_reports_q1']:.0f}–{ex['cohort_reports_q3']:.0f}; range {f(ex['cohort_reports_min'])}–{f(ex['cohort_reports_max'])}). ClinicalTrials.gov extract: {f(ex['ctgov_trials_in_extract'])} trials. Software: " + ", ".join(f"{k} {v}" for k, v in ex['software'].items()) + ".")
if p2: A(f"- Independent re-derivation from the specification only [`private/reviews/P2_numbers.json`, `P2_independent_rederivation.md`]: 0.5994 same-target, 0.0601 different-target, contrast 0.8613, on 1,110 molecules, 197 targets and 8,186 same-target pairs. The re-derivation read the target table with pandas default missing-value parsing, which drops the symbol NA (neuraminidase; line 133 of its script), and used a slightly different salt-word list; these account for 197 vs 198 targets and 8,186 vs 8,117 pairs. Estimates agree to within 0.001.")
A("\n## 4. Sensitivity grid (999 permutations, 1,000 bootstrap) [`results/tables/sensitivity_grid.csv`]")
A("| extraction | ranking | K | cleaned | molecules | same pairs | mean same | mean different | Δ | 95% CI | p |"); A("|---|---|---|---|---|---|---|---|---|---|---|")
for r in grid.itertuples(): A(f"| {r.extraction} | {r.ranking} | {r.K} | {'yes' if r.cleaned else 'no'} | {f(r.molecules)} | {f(r.same_pairs)} | {r.pair_mean_same} | {r.pair_mean_different} | {r.delta} | {r.ci_lo}–{r.ci_hi} | {r.p_perm} |")
A("\nExtractions: a any role; b primary + secondary suspect; c primary suspect only; d as b, health-professional reporters only.")
A("\n## 5. Co-mention [`results/tables/comention_summary.json`, `comention_pairs.csv.gz`]")
for g in ("same", "different"):
    d = cm[g]; A(f"- {g} target: {f(d['pairs'])} pairs; median co-mention share {d['median_share_max']*100:.3f}%; share ≥5% in {d['pct_share_ge_5pct']}%; no shared report in {d['pct_no_comention']}%; mean overlap {d['mean_overlap_before']} → {d['mean_overlap_after']} after removing reports that name both molecules.")
A(f"- Difference (same − different): before {cm['difference_before']['estimate']} (95% CI {cm['difference_before']['ci95'][0]}–{cm['difference_before']['ci95'][1]}); after exclusion {cm['difference_after']['estimate']} (95% CI {cm['difference_after']['ci95'][0]}–{cm['difference_after']['ci95'][1]}).")
A("| co-mention share | same: pairs | same: before → after | different: pairs | different: before → after |"); A("|---|---|---|---|---|")
for s in cm["strata"]: A(f"| {s['share_from']*100:g}%–{min(s['share_to'],1)*100:g}% | {f(s['same']['pairs'])} | {s['same']['before']} → {s['same']['after']} | {f(s['different']['pairs'])} | {s['different']['before']} → {s['different']['after']} |")
A("\n## 6. H2 — adjusted pair regression and therapeutic-area 2×2 [`results/tables/h2_regression.json`]")
A("| same target | same ATC level 3 | pairs | mean overlap | after co-mention exclusion |"); A("|---|---|---|---|---|")
for t in h2["area_2x2"]: A(f"| {'yes' if t['same_target'] else 'no'} | {'yes' if t['same_atc3'] else 'no'} | {f(t['pairs'])} | {t['mean_overlap']} | {t['mean_overlap_comention_excluded']} |")
for m, lab in (("model_unadjusted", "Unadjusted"), ("model_adjusted_H2", "Adjusted (H2, pre-specified)"), ("model_adjusted_comention_excluded_outcome", "Adjusted, outcome after co-mention exclusion"), ("model_adjusted_with_epc", "Adjusted + same FDA EPC class (exploratory)")):
    c = h2[m]["coefficients"]["same_target"]; A(f"- {lab}: {f(h2[m]['pairs'])} pairs; same-target coefficient {c['beta']} (95% CI {c['ci95'][0]}–{c['ci95'][1]}; bootstrap share ≤ 0: {c['p_one_sided_le0']}).")
c = h2["model_adjusted_H2"]["coefficients"]; A("- Other coefficients in the H2 model: " + "; ".join(f"{k} {v['beta']} ({v['ci95'][0]}–{v['ci95'][1]})" for k, v in c.items() if k not in ("intercept", "same_target")) + ".")
A("\n## 7. H3 — as-of-date test [`results/tables/asof_summary.json`, `asof_sets.csv`]")
A(f"- Candidate first→successor sets {h3['candidate_sets']}; matched sets {h3['matched_sets']} (dropped: {h3['dropped']}); {h3['clusters']} clusters; {h3['distinct_F']} first molecules, {h3['distinct_S']} successors.")
for k in ("clean", "raw"):
    o = h3[k]; A(f"- {k}: first molecule's as-of profile shares {o['mean_O_F']} signals with the successor; control A {o['mean_control_A']}; control B {o['mean_control_B']}. e_A = {o['eA']['estimate']} (95% CI {o['eA']['ci95'][0]}–{o['eA']['ci95'][1]}; sign-flip p {o['eA']['p_signflip_one_sided']}); e_B = {o['eB']['estimate']} ({o['eB']['ci95'][0]}–{o['eB']['ci95'][1]}; p {o['eB']['p_signflip_one_sided']}); θ_A = {o['thetaA']['estimate']} ({o['thetaA']['ci95'][0]}–{o['thetaA']['ci95'][1]}). Sets with ≥1 shared signal: {o['share_sets_F_ge1']*100:.1f}% vs {o['share_control_A_ge1']*100:.1f}% of control-A comparisons.")
A("\n## 8. H4 — ClinicalTrials.gov replication [`data/derived/ctgov/*.json`, `results/tables/primary_H4_ctgov_*.json`, `private/reviews/P3_arm_audit_*`]")
A(f"- Arm attribution v2: {f(at['labels']['exposed'])} monotherapy arms of {f(at['arms'])}; audit precision 93/100 (v1 failed: tier 1 73/100, tier 2 24/98 and was dropped).")
A(f"- Term matching: {ct['pct_rows_kept']}% of event rows and {ct['pct_affected_subjects_kept']}% of affected subjects kept ({f(ct['distinct_terms_matched'])} FAERS terms matched from {f(ct['distinct_raw_terms'])} raw terms).")
A(f"- Molecules meeting minimum data: {ct['molecules_meeting_minimum_data']}; replication cohort {ct['cohort_molecules']} molecules, {ct['cohort_targets']} targets, {f(ct['same_target_pairs_within_cohort_targets'])} same-target pairs within cohort targets; assessable: {ct['assessable']}.")
for lab, h in (("All pairs", h4), ("Pairs with no shared top-10 trial condition", h4r)):
    x, e = h["shared_signals"], h["excess"]; A(f"- {lab}: {h['same_target_pairs']:,} same-target and {h['different_target_pairs']:,} different-target pairs; Δ_CT = {x['delta']} (95% CI {x['ci95'][0]}–{x['ci95'][1]}; p {x['p_perm_one_sided']}; molecules used {x['molecules_used']}); pair means {x['pair_mean_same']} vs {x['pair_mean_different']}; excess-overlap Δ_X = {e['delta']} (95% CI {e['ci95'][0]}–{e['ci95'][1]}).")
wt = J("data/derived/ctgov/profile_within_trial/summary.json"); hw = J("results/tables/primary_H4_ctgov_within_trial.json")
A(f"- Key sensitivity, within-trial reference-arm-adjusted profiles (Mantel–Haenszel) [`data/derived/ctgov/profile_within_trial/summary.json`, `primary_H4_ctgov_within_trial.json`]: {f(wt['trials_with_exposed_and_reference'])} trials have both a monotherapy and a reference arm; {wt['molecules_meeting_minimum_data']} molecules meet minimum data; cohort {wt['cohort_molecules']} molecules, {wt['cohort_targets']} targets, {wt['same_target_pairs_within_cohort_targets']} same-target pairs — **not assessable** against the pre-set size thresholds (≥200 molecules, ≥50 targets, ≥1,000 pairs). Descriptive only: Δ = {hw['shared_signals']['delta']} (95% CI {hw['shared_signals']['ci95'][0]}–{hw['shared_signals']['ci95'][1]}), pair means {hw['shared_signals']['pair_mean_same']} vs {hw['shared_signals']['pair_mean_different']}. The main replication profile is therefore the arm-level one, with other molecules' monotherapy arms as background.")
A("- Verdict against the pre-set criterion (SAP_draft §8.5): (i) Δ_CT > 0 with p < 0.025, (ii) CI of Δ_X above 0, (iii) CI of Δ_X above 0 with shared-condition pairs excluded — all three met: **replicated**.")
open(os.path.join(P, "results/RESULTS_SUMMARY.md"), "w").write("\n".join(L) + "\n"); print("\n".join(L))
